macro.command:
const version = "13.0.52";
try {
    if (!["mwak"].includes(rolledActivity.actionType)) return {};
    if (workflow.hitTargets.size === 0) return {};
    // Find available spell slots (level 1-5, capped at 5d8 max)
    const spells = actor.system.spells;
    let options = "";
    for (let i = 1; i <= 9; i++) {
        const slot = spells[`spell${i}`];
        if (slot && slot.value > 0) {
            const numDice = Math.min(1 + i, 5);
            options += `<option value="spell${i}">${slot.label} (${slot.value}) ${numDice}d8</option>`;
        }
    }
    if (spells.pact?.value > 0 && spells.pact?.level > 0) {
        const numDice = Math.min(1 + spells.pact.level, 5);
        options += `<option value="pact">${spells.pact.label} (${spells.pact.value}) ${numDice}d8</option>`;
    }
    if (!options) return {};
    const useLabel = game.i18n.localize("DND5E.AbilityUseCast");
    const choice = await foundry.applications.api.DialogV2.wait({
        window: {title: macroItem.name},
        position: {width: 400},
        content: `<form><p>${useLabel} ${macroItem.name}?</p><select name="slotKey">${options}</select></form>`,
        buttons: [
            {action: "use", label: useLabel, default: true, callback: (event, button) => button.form.elements.slotKey.value},
            {action: "no", label: game.i18n.localize("Cancel"), callback: () => false}
        ],
        close: () => false
    });
    if (!choice) return {};
    // Consume the spell slot
    const slotKey = choice;
    const slotPath = `system.spells.${slotKey}`;
    const current = foundry.utils.getProperty(actor, slotPath);
    if (current.value <= 0) return {};
    await actor.update({[`${slotPath}.value`]: current.value - 1});
    // Calculate damage dice
    const slotLevel = current.level;
    let numDice = Math.min(1 + slotLevel, 5);
    // Check for undead/fiend
    const target = workflow.hitTargets.first();
    const creatureType = (target?.actor?.system?.details?.type?.value || "").toLowerCase();
    if (["undead", "fiend"].includes(creatureType)) numDice += 1;
    // Build the damage roll respecting critical hits
    const isCritical = workflow.isCritical;
    return await new CONFIG.Dice.DamageRoll(`${numDice}d8`, {}, {type: "radiant", isCritical, flavor: macroItem.name}).evaluate();
} catch (err) {
    console.error(`${macroItem.name} ${version}`, err);
    return {};
}
